import{_ as a,o as r,c as o,a0 as d}from"./chunks/framework.Bmhw_dvp.js";const g=JSON.parse('{"title":"详细使用手册","description":"","frontmatter":{"title":"详细使用手册"},"headers":[],"relativePath":"docs/usage.md","filePath":"docs/usage.md"}'),e={name:"docs/usage.md"};function l(i,t,n,s,h,c){return r(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="nuim-详细使用手册" tabindex="-1">NUIM 详细使用手册 <a class="header-anchor" href="#nuim-详细使用手册" aria-label="Permalink to &quot;NUIM 详细使用手册&quot;">​</a></h1><blockquote><p>面向 <strong>终端使用者</strong> 的一站式操作指引，涵盖即时通讯、办公应用、AI 助手/群助手、分身、文件空间与通知提醒。 开发/集成方请见 <a href="/docs/cli">CLI 使用指南</a> 与 <a href="/docs/mcp">MCP 接入指南</a>。</p></blockquote><hr><h2 id="一、登录与会话" tabindex="-1">一、登录与会话 <a class="header-anchor" href="#一、登录与会话" aria-label="Permalink to &quot;一、登录与会话&quot;">​</a></h2><h3 id="登录" tabindex="-1">登录 <a class="header-anchor" href="#登录" aria-label="Permalink to &quot;登录&quot;">​</a></h3><ol><li>启动应用，输入用户名、密码。</li><li>可选：勾选「记住密码」（本地<strong>加密存储</strong>），下次自动登录。</li><li>后端不在本机时，可在登录界面「设置服务器地址」修改（默认 <code>http://localhost:8080</code>）。</li></ol><h3 id="会话类型" tabindex="-1">会话类型 <a class="header-anchor" href="#会话类型" aria-label="Permalink to &quot;会话类型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>说明</th><th>入口</th></tr></thead><tbody><tr><td><strong>单聊 / 私聊</strong></td><td>一对一加密沟通</td><td>左侧「组织架构」→ 双击或「发起私聊」</td></tr><tr><td><strong>群聊</strong></td><td>多人协作，群公告、群文件、管理员</td><td>左侧「+」→「创建群聊」</td></tr><tr><td><strong>讨论组</strong></td><td>扁平化讨论，成员平等参与</td><td>「+」→「创建讨论组」</td></tr><tr><td><strong>频道</strong></td><td>订阅制信息发布，富文本 Markdown、审批机制</td><td>「+」→「频道」</td></tr></tbody></table><h3 id="会话管理" tabindex="-1">会话管理 <a class="header-anchor" href="#会话管理" aria-label="Permalink to &quot;会话管理&quot;">​</a></h3><ul><li><strong>置顶</strong>：固定重要会话到列表顶部。</li><li><strong>免打扰 / 隐藏</strong>：减少干扰或隐藏会话。</li><li><strong>消息搜索 / 漫游</strong>：按关键词、日期、类型筛选，多端同步。</li></ul><hr><h2 id="二、消息通信" tabindex="-1">二、消息通信 <a class="header-anchor" href="#二、消息通信" aria-label="Permalink to &quot;二、消息通信&quot;">​</a></h2><h3 id="消息类型" tabindex="-1">消息类型 <a class="header-anchor" href="#消息类型" aria-label="Permalink to &quot;消息类型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>📝 文本</td><td>URL 自动识别转链接</td></tr><tr><td>🖼️ 图片</td><td>大图预览</td></tr><tr><td>📎 文件</td><td>上传、下载、另存</td></tr><tr><td>🔗 分享</td><td>笔记、便签、文件分享到用户/群聊</td></tr><tr><td>📱 小程序卡片</td><td>内嵌应用卡片</td></tr><tr><td>📰 资讯卡片</td><td>富文本资讯</td></tr><tr><td>🤖 Bot 卡片</td><td>带按钮的交互卡片，支持状态回写</td></tr></tbody></table><h3 id="常用操作" tabindex="-1">常用操作 <a class="header-anchor" href="#常用操作" aria-label="Permalink to &quot;常用操作&quot;">​</a></h3><ul><li><strong>引用 / 回复</strong>：悬停消息 → 回复，上下文清晰。</li><li><strong>撤回 / 编辑</strong>：2 分钟内撤回，撤回后可重新编辑回填。</li><li><strong>@ 提及</strong>：<code>@</code> 指定成员或 <code>@全体成员</code>。</li><li><strong>已读回执</strong>：群聊显示已读人数，单聊显示已读状态。</li><li><strong>语音 / 视频</strong>：WebRTC 音视频通话、屏幕共享（禁止对 AI 助手发起屏幕共享）。</li></ul><hr><h2 id="三、应用中心" tabindex="-1">三、应用中心 <a class="header-anchor" href="#三、应用中心" aria-label="Permalink to &quot;三、应用中心&quot;">​</a></h2><p>左侧栏「应用」进入：</p><table tabindex="0"><thead><tr><th>应用</th><th>说明</th></tr></thead><tbody><tr><td>📊 统计报表</td><td>消息趋势、文件分布、任务完成率可视化</td></tr><tr><td>📅 日历</td><td>月视图，事件管理，支持提醒</td></tr><tr><td>📝 笔记</td><td>Markdown 编辑器，实时预览，可分享</td></tr><tr><td>📌 便签</td><td>快捷笔记，多色分类</td></tr><tr><td>📁 文件管理</td><td>个人文件、群文件空间、上传下载、分级权限</td></tr><tr><td>✅ 任务管理</td><td>看板视图，待办/进行中/已完成</td></tr><tr><td>🤖 AI 助手</td><td>智能对话机器人</td></tr><tr><td>🔗 短链接</td><td>URL 缩短与管理</td></tr></tbody></table><p><strong>分享内容</strong>：笔记/便签/文件 →「分享」→ 选择用户或群聊 → 发送。</p><hr><h2 id="四、ai-助手与群助手" tabindex="-1">四、AI 助手与群助手 <a class="header-anchor" href="#四、ai-助手与群助手" aria-label="Permalink to &quot;四、AI 助手与群助手&quot;">​</a></h2><h3 id="ai-助手" tabindex="-1">AI 助手 <a class="header-anchor" href="#ai-助手" aria-label="Permalink to &quot;AI 助手&quot;">​</a></h3><p>「应用」→「AI 助手」→ 选择机器人对话。支持多模型、智能摘要、智能搜索。</p><h3 id="群聊-ai-助手" tabindex="-1">群聊 AI 助手 <a class="header-anchor" href="#群聊-ai-助手" aria-label="Permalink to &quot;群聊 AI 助手&quot;">​</a></h3><p>群聊中可启用 AI 助手代答，三种触发方式：</p><ol><li><strong><code>@AI</code> 触发</strong>：<code>@AI</code> + 提问，群助手优先响应。</li><li><strong>关键词门控</strong>：配置关键词，命中自动回复。</li><li><strong>代管成员</strong>：群助手托管指定成员，被 @ 时代答。</li></ol><p><strong>群级记忆与知识库</strong>：</p><ul><li><strong>群知识库</strong>：群显式上传的权威文档，回答&quot;事实是什么&quot;。</li><li><strong>群记忆</strong>：从对话自动提炼的共识/约定/偏好，回答&quot;这个群默认怎么做事&quot;。</li><li>两者独立存储、刻意隔离。</li></ul><h3 id="帮我回复" tabindex="-1">帮我回复 <a class="header-anchor" href="#帮我回复" aria-label="Permalink to &quot;帮我回复&quot;">​</a></h3><p>收到消息可用「帮我回复」生成草稿（复用分身流式生成能力），编辑后发送。</p><hr><h2 id="五、ai-分身-avatar" tabindex="-1">五、AI 分身 / Avatar <a class="header-anchor" href="#五、ai-分身-avatar" aria-label="Permalink to &quot;五、AI 分身 / Avatar&quot;">​</a></h2><p>分身让你离线时代为回复，是核心 AI 能力。</p><ul><li><strong>人设</strong>：分析历史对话自动学习你的表达风格与角色定位。</li><li><strong>触发规则</strong>：在合适时机代为回复。</li><li><strong>知识范围</strong>：<code>notes</code>（主人笔记）、<code>tasks</code>（任务）知识开关控制回答领域。</li><li><strong>回复策略</strong>：仿真人延迟，避免机械感。</li><li><strong>记忆</strong>：分身从对话中提炼风格与偏好，支持三态会话激活、置信度门控、手动接管。</li></ul><hr><h2 id="六、文件空间与知识库" tabindex="-1">六、文件空间与知识库 <a class="header-anchor" href="#六、文件空间与知识库" aria-label="Permalink to &quot;六、文件空间与知识库&quot;">​</a></h2><h3 id="文件空间" tabindex="-1">文件空间 <a class="header-anchor" href="#文件空间" aria-label="Permalink to &quot;文件空间&quot;">​</a></h3><ul><li><strong>个人文件空间</strong>：你的上传/下载、排序、消息引用。</li><li><strong>群文件空间</strong>：群成员共享，集中式权限校验 + scope 隔离。</li></ul><h3 id="群知识库" tabindex="-1">群知识库 <a class="header-anchor" href="#群知识库" aria-label="Permalink to &quot;群知识库&quot;">​</a></h3><p>群知识库面向群助手/分身检索（上传 → 解析分块 → 向量化），与普通群文件是两套体系。公共文档由管理后台「文档管理」多版本维护。</p><hr><h2 id="七、通知与提醒" tabindex="-1">七、通知与提醒 <a class="header-anchor" href="#七、通知与提醒" aria-label="Permalink to &quot;七、通知与提醒&quot;">​</a></h2><ul><li><strong>待办提醒</strong>：任务/事件定时触发通知；管理后台可调提醒门槛、重复冷却。</li><li><strong>通知中心</strong>：聚合通知，点频道消息可跳转。</li><li><strong>调度</strong>：任务、日历、提醒、通知可后台调度触发。</li></ul><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/docs/features">功能介绍</a></li><li><a href="/docs/cli">CLI 使用指南</a>（开发集成）</li><li><a href="/docs/mcp">MCP 接入指南</a>（开发集成）</li></ul>',48)])])}const b=a(e,[["render",l]]);export{g as __pageData,b as default};
